{
  "version": "2.0.0",
  "tasks": [
    {
      "label": "Doctor: Run Diagnostics",
      "type": "shell",
      "command": "pnpm kubit-forge doctor",
      "group": "test",
      "presentation": {
        "reveal": "always",
        "panel": "new"
      }
    },
    {
      "label": "Doctor: Auto-Fix",
      "type": "shell",
      "command": "pnpm kubit-forge doctor:fix --dry-run",
      "group": "test"
    },
    {
      "label": "Doctor: Export for VS Code",
      "type": "shell",
      "command": "pnpm kubit-forge doctor:export --format vscode --output .vscode/diagnostics.json",
      "group": "build"
    }
  ]
}
